import{_ as d,o as e,c as i,ag as a}from"./chunks/framework.CPvOxTBX.js";const k=JSON.parse('{"title":"词典格式","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/dictionary-formats.md","filePath":"zh/guide/dictionary-formats.md","lastUpdated":1793438909000}'),o={name:"zh/guide/dictionary-formats.md"};function s(c,t,r,l,n,h){return e(),i("div",null,t[0]||(t[0]=[a(`<h1 id="词典格式" tabindex="-1">词典格式 <a class="header-anchor" href="#词典格式" aria-label="Permalink to &quot;词典格式&quot;">​</a></h1><p>词悦读取两类词典：<strong>MDict</strong>（<code>.mdx</code> / <code>.mdd</code>）与 <strong>StarDict</strong>（<code>.ifo</code> / <code>.idx</code> / <code>.dict</code>）。它们装的是同一类东西——词头、HTML 或纯文本释义，以及释义里引用的图片和 音频——但内部结构完全不同，这个差别决定了词典怎么转换、怎么打补丁、出问题时从哪查。</p><p>本文说明两种格式的内部结构、词悦实际能读什么，以及如何在两者之间转换。</p><div class="warning custom-block"><p class="custom-block-title">一个主文件名只能有一本词典</p><p>词悦用「去掉扩展名的路径」标识词典，所以同一目录下的 <code>dict.mdx</code> 与 <code>dict.ifo</code> 会被当成 同一本，只会导入 MDX 那份。想两本都留着，就把主文件名区分开，例如 <code>dict-mdx.mdx</code> 和 <code>dict-stardict.ifo</code>。</p></div><h2 id="mdict" tabindex="-1">MDict <a class="header-anchor" href="#mdict" aria-label="Permalink to &quot;MDict&quot;">​</a></h2><p>一本 MDict 词典是一个 <code>.mdx</code> 文件加若干可选的资源文件：</p><table tabindex="0"><thead><tr><th>文件</th><th>内容</th></tr></thead><tbody><tr><td><code>name.mdx</code></td><td>词头与释义</td></tr><tr><td><code>name.mdd</code></td><td>图片、音频、CSS、JS</td></tr><tr><td><code>name.1.mdd</code>、<code>name.2.mdd</code></td><td>更多的资源包（<code>1</code>、<code>2</code> 是文件名的一部分）</td></tr></tbody></table><p>它们的主文件名必须一致。导入时词悦只需要 <code>name.mdx</code>，但资源只有和 <code>.mdx</code> 放在同一 目录时才找得到。</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>MDict 本身是闭源的免费软件（Octopus Studio），格式从未公开过规范，所有开源读取器 ——包括词悦用的那个——都是从文件里逆向出来的。这也是各家工具支持范围不一致的原因： 1.2 与 2.0（头部里的 <code>GeneratedByEngineVersion</code>）是大家都能读的版本；3.0 改了编码 规则，只有部分实现支持，不过用 3.0 打包的词典很少见。</p></div><p><code>.mdx</code> 内部依次是：4 字节的头长度、UTF-16LE 的 XML 头（<code>Title</code>、<code>Description</code>、 <code>Encoding</code>、<code>StyleSheet</code> 等）、键索引区、记录区。索引和记录都按块压缩，查一个词只 解压需要的那一块。<code>.mdd</code> 用同样的容器，只是把文件路径当作键。实际释义基本都是 HTML， 资源用相对路径引用。</p><p>词悦能读 <code>.mdd</code> 与拆分出来的 <code>.N.mdd</code>；资源不在压缩包里时会回退到 <code>.mdx</code> 同目录下的 散文件。用 LZO 压缩的 MDX 会在导入时报「不支持的压缩方式」：请用 zlib 重新压缩，或者 转成别的格式。</p><h3 id="桌面上的事实标准其实是-goldendict-ng" tabindex="-1">桌面上的事实标准其实是 GoldenDict-ng <a class="header-anchor" href="#桌面上的事实标准其实是-goldendict-ng" aria-label="Permalink to &quot;桌面上的事实标准其实是 GoldenDict-ng&quot;">​</a></h3><p>MDict 自己用老版 IE 的 WebBrowser 控件渲染词条（IE7/8 一代，JavaScript 停在 ES5）， 所以依赖 flexbox、<code>word-break</code>、<code>localStorage</code> 或 ES6 的现代 <code>.mdx</code>，在定义了这个格式的 「原版」软件里根本显示不正常。而 PC 上大家实际用的是 GoldenDict-ng，于是它——而不是 MDict——成了新词典的事实参考实现。<a href="https://lib.rs/crates/pangloss" target="_blank" rel="noreferrer"><code>pangloss</code></a> 的文档里就写得很直接：</p><blockquote><p>每个有实际分量的格式都对应一个具体的阅读器——Mdict 对应的就是 goldendict-ng；其他阅读器也许能导入这种格式，但通常支持不到相同 的功能范围。</p></blockquote><table tabindex="0"><thead><tr><th>格式</th><th>目标阅读器</th></tr></thead><tbody><tr><td>Yomitan</td><td>Yomitan</td></tr><tr><td>StarDict</td><td>KOReader</td></tr><tr><td>MDict</td><td>GoldenDict-ng</td></tr><tr><td>DSL（只读）</td><td>GoldenDict-ng</td></tr></tbody></table><p>这种「照着 GoldenDict-ng 写、而不是照着 MDict 写」的痕迹随处可见。例如不少第三方 打包的 <code>.mdx</code> 里直接带着 <code>bword://word</code> 链接——<code>bword://</code> 本是 Babylon <code>.bgl</code> 格式的跳转写法，原版 MDict 根本不认；它之所以能跳，是因为 GoldenDict-ng 把 <code>bword://</code> 和 <code>entry://</code> 当作同一个 scheme 处理。换言之，连 MDict 自家格式的文件， 作者都在按 GoldenDict-ng 的行为来写链接了。</p><p>某本词典在某个软件里「排版坏了」，先确认它是照着哪个阅读器做的：作者通常按最新的引擎 写，而不是按最老的那个。</p><h2 id="stardict" tabindex="-1">StarDict <a class="header-anchor" href="#stardict" aria-label="Permalink to &quot;StarDict&quot;">​</a></h2><p>StarDict 是同一目录下一组同名文件：</p><table tabindex="0"><thead><tr><th>文件</th><th>是否必需</th><th>内容</th></tr></thead><tbody><tr><td><code>name.ifo</code></td><td>必需</td><td>纯文本元信息：<code>bookname</code>、<code>wordcount</code>、<code>idxfilesize</code>、<code>sametypesequence</code> 等</td></tr><tr><td><code>name.idx</code></td><td>必需</td><td>词头索引</td></tr><tr><td><code>name.dict</code></td><td>必需</td><td>释义正文</td></tr><tr><td><code>name.syn</code></td><td>可选</td><td>同义词索引</td></tr></tbody></table><p><code>bookname</code> 就是词悦里显示的词典名。<code>.idx</code> 的每条记录是：UTF-8 词头、一个 <code>\\0</code>、 4 字节大端偏移、4 字节大端长度，指向 <code>.dict</code> 中的位置；记录按字节序排序，二分查找才 能成立。<code>.ifo</code> 里写了 <code>idxoffsetbits=64</code> 的词典改用 8 字节偏移（StarDict 3.0 的布局）。</p><p><code>.dict</code> 存放释义。有 <code>sametypesequence</code> 时，每条记录就是这些类型的字段直接拼接、不带 类型字节；没有时，每个字段前面都带一个类型字节。常见类型：</p><table tabindex="0"><thead><tr><th>类型</th><th>含义</th></tr></thead><tbody><tr><td><code>m</code></td><td>纯文本</td></tr><tr><td><code>h</code></td><td>HTML</td></tr><tr><td><code>g</code></td><td>Pango 标记</td></tr><tr><td><code>x</code></td><td>XDXF</td></tr><tr><td><code>t</code></td><td>音标</td></tr><tr><td><code>y</code></td><td>汉语拼音 / 日文假名</td></tr><tr><td><code>r</code></td><td>资源文件列表</td></tr><tr><td><code>W</code></td><td>WAV 音频</td></tr><tr><td><code>P</code></td><td>图片</td></tr></tbody></table><p><code>.idx</code>、<code>.syn</code>、<code>.dict</code> 都可以压缩存放：<code>.idx.gz</code> / <code>.syn.gz</code> 是普通 gzip， <code>.dict.dz</code> 是 dictzip——同样兼容 gzip 的容器，但每块独立压缩、可随机读取，所以查词 不用整本解压。词悦三种写法都能读。</p><h3 id="资源文件-res-与-res-zip" tabindex="-1">资源文件：<code>res/</code> 与 <code>res.zip</code> <a class="header-anchor" href="#资源文件-res-与-res-zip" aria-label="Permalink to &quot;资源文件：\`res/\` 与 \`res.zip\`&quot;">​</a></h3><p>StarDict 本身没有资源容器：图片和音频放在词典旁边的 <code>res/</code> 目录里，词条用 <code>res/pic.png</code> 或 <code>pic.png</code> 引用。</p><p>GoldenDict-ng 在这个基础上允许把同一个目录直接打成 zip，不必解压：</p><table tabindex="0"><thead><tr><th>路径</th><th>说明</th></tr></thead><tbody><tr><td><code>res/</code></td><td>普通目录</td></tr><tr><td><code>res.zip</code></td><td>根目录就是 <code>res/</code> 内容的压缩包</td></tr><tr><td><code>name.res.zip</code></td><td>同上，以词典名命名</td></tr></tbody></table><p>压缩包里<strong>不能再套一层 <code>res/</code></strong>——它的根目录本身就是 <code>res/</code>。词悦依次查找 <code>res/</code>、 <code>res.zip</code>、<code>name.res.zip</code>、<code>res/res.zip</code>，压缩包内 <code>pic.png</code> 和 <code>res/pic.png</code> 两种 写法都认，所以按 GoldenDict-ng 规则打包的 zip 可以直接用。</p><h2 id="该选哪种" tabindex="-1">该选哪种 <a class="header-anchor" href="#该选哪种" aria-label="Permalink to &quot;该选哪种&quot;">​</a></h2><ul><li><strong>MDict</strong> 压缩率更高、只有一个文件，所以公开发布的词典大多是这个格式；代价是不好 打开，读或改都要借助工具。</li><li><strong>StarDict</strong> 是明文文件和极简的索引格式，容易查看、比较、手工修补，几乎所有的开源 词典软件都支持。配合 <code>res.zip</code> 与 <code>.dict.dz</code>，也不会再产生成千上万个小文件。</li></ul><h2 id="格式转换" tabindex="-1">格式转换 <a class="header-anchor" href="#格式转换" aria-label="Permalink to &quot;格式转换&quot;">​</a></h2><p>词悦本身不写这两种格式，转换要用下面的工具。</p><h3 id="mdict-→-stardict-pyglossary" tabindex="-1">MDict → StarDict（pyglossary） <a class="header-anchor" href="#mdict-→-stardict-pyglossary" aria-label="Permalink to &quot;MDict → StarDict（pyglossary）&quot;">​</a></h3><p><a href="https://github.com/ilius/pyglossary" target="_blank" rel="noreferrer">pyglossary</a> 需要 Python 3.12 或更新版本：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pyglossary</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pyglossary</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> book.mdx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> book.ifo</span></span></code></pre></div><p>格式按扩展名自动识别；不确定时用 <code>--read-format</code> / <code>--write-format</code> 显式指定 （<code>pyglossary --help</code> 会列出可用的名字）。常用参数：</p><ul><li><code>--sqlite</code>：中间数据落在 SQLite 而不是内存里，大词典必加；</li><li><code>--no-interactive</code>：脚本里用，必须同时给出输入和输出文件名；</li><li><code>--remove-html-all</code>：去掉释义里的 HTML（需要 <code>lxml</code> 和 <code>beautifulsoup4</code>），一般 不建议——HTML 正是排版和图片的来源。</li></ul><p>StarDict 输出必须排序，所以 pyglossary 自己也可能切到 SQLite 模式。</p><h3 id="stardict-→-mdict-mdict-utils" tabindex="-1">StarDict → MDict（mdict-utils） <a class="header-anchor" href="#stardict-→-mdict-mdict-utils" aria-label="Permalink to &quot;StarDict → MDict（mdict-utils）&quot;">​</a></h3><p>pyglossary 能读 MDX，但不能写。反方向要用 <a href="https://github.com/zhansliu/mdict-utils" target="_blank" rel="noreferrer">mdict-utils</a> 打包它约定的纯文本：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mdict-utils</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mdict</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> source.txt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> book.mdx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --title</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;我的词典&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --description</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;...&quot;</span></span></code></pre></div><p><code>source.txt</code> 一本一词条：词头单独一行，释义紧随其后，条目之间用 <code>&lt;/&gt;</code> 分隔。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>word</span></span>
<span class="line"><span>&lt;p&gt;释义&lt;/p&gt;</span></span>
<span class="line"><span>&lt;/&gt;</span></span></code></pre></div><p>pyglossary 导出的制表符文本离这个格式只差一步，写几行脚本按制表符拆分、在条目之间补 <code>&lt;/&gt;</code> 即可。</p><p>同一个工具也适合日常检查：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mdict</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> book.mdx</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 看头部信息</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mdict</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -k</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> book.mdx</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 看前几个词头</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mdict</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -q</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> word</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> book.mdx</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 查一条词条</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mdict</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> book.mdx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> out/</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 解包词条与 .mdd 资源</span></span></code></pre></div><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><ul><li><strong>主文件名要一致。</strong> 把一对文件（<code>.mdx</code> + <code>.mdd</code>）或三件套（<code>.ifo</code> + <code>.idx</code> + <code>.dict</code>）里的某一个改名，词典就废了；要改就一起改。</li><li><strong><code>res.zip</code> 不要套外层目录</strong>，否则在 GoldenDict-ng 里会读不到资源。</li><li><strong>转换后确认词典名。</strong> 名字来自 MDict 头部或 StarDict 的 <code>bookname</code>，取决于转换器 写了什么；空的会退回到文件名。</li><li><strong>发音可能失效。</strong> pyglossary 会把 MDict 的 <code>&lt;a href=&quot;sound://…&quot;&gt;</code> 改写成 <code>&lt;audio src=&quot;…&quot;&gt;</code>，部分阅读器不渲染这种写法。转换后喇叭图标消失，通常就是它。</li></ul><h2 id="去哪里找词典" tabindex="-1">去哪里找词典 <a class="header-anchor" href="#去哪里找词典" aria-label="Permalink to &quot;去哪里找词典&quot;">​</a></h2><ul><li><a href="https://forum.freemdict.com/" target="_blank" rel="noreferrer">FreeMdict 论坛</a>——MDX/StarDict 词典最大的社区，有 格式讨论和转换经验。</li><li><a href="https://xiaoyifang.github.io/goldendict-ng/dictformats/" target="_blank" rel="noreferrer">GoldenDict-ng 的格式说明</a> ——<code>res.zip</code>、dictzip 等扩展写法的参考。</li></ul><p>下载或转换时请遵守词典的授权条款，很多词典只允许个人使用。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="./getting-started.html">快速上手</a>——添加词典。</li><li><a href="./word-forms.html">词形还原</a>——Hunspell 文件，与词典格式无关。</li><li><a href="./faq.html">常见问题</a>——导入报错与显示问题。</li></ul>`,54)]))}const g=d(o,[["render",s]]);export{k as __pageData,g as default};
